object Email {
  def unapply(s: String): Option[Email] = s match {
    case emailRegex(u, d, _) => Some(Email(u, d))
    case _ => None
  }
}

"alice@example.com" match {
  case Email(user, domain) => println(s"$user at $domain")
}

ScalaTest (FlatSpec/WordSpec):
import org.scalatest.flatspec.AnyFlatSpec
import org.scalatest.matchers.should.Matchers

class CalculatorSpec extends AnyFlatSpec with Matchers {
  "A Calculator" should "add two numbers" in {
    val calc = Calculator()
    calc.add(2, 3) should be (5)
  }

  it should "handle negative numbers" in {
    Calculator().add(-1, 1) should be (0)
  }

  it should "throw on division by zero" in {
    an [ArithmeticException] should be thrownBy {
      Calculator().divide(1, 0)
    }
  }
}

Property-Based Testing:
import org.scalatest.flatspec.AnyFlatSpec
import org.scalatestplus.scalacheck.ScalaCheckPropertyChecks

class StringSpec extends AnyFlatSpec with ScalaCheckPropertyChecks {
  "String reversal" should "be its own inverse" in {
    forAll { (s: String) =>
      s.reverse.reverse shouldBe s
    }
  }

  it should "preserve length" in {
    forAll { (s: String) =>
      s.reverse.length shouldBe s.length
    }
  }
}

